{"type":"user","message":{"role":"user","content":[{"tool_use_id":"chatcmpl-tool-bd9a8eab3a6db326","type":"tool_result","content":"1\t#!/usr/bin/env python3\n2\t\"\"\"Deterministic pre-submit validation for one strategy's epic decomposition.\n3\t\n4\tChecks the mechanically decidable contract rules that the downstream judges\n5\tand submit.py enforce — the ones an LLM step can silently get wrong while the\n6\tdecomposition still looks good:\n7\t\n8\t  1. Epic body sections: every epic file must carry headings covering\n9\t     Description, Scope, Acceptance Criteria, and HLR Traceability (matched on\n10\t     heading text at any level, exactly like the artifact contract).\n11\t  2. Component vocabulary: every epic's `component` frontmatter value must be\n12\t     verbatim in .context/rhai-components.txt (submit.py silently strips\n13\t     unknown names, leaving the Jira epic component-less).\n14\t  3. Rule 11 (docs-last): every docs-authoring epic must be blocked, directly\n15\t     or transitively, by every main-plan Implementation epic that is not\n16\t     itself docs-authoring.\n17\t  4. Priority inheritance: an epic that directly or transitively enables a P0\n18\t     epic must itself be P0 (docs-authoring epics are exempt; branch epics\n19\t     are conditional alternatives and out of scope).\n20\t  5. Implementation-type parallelism (Rules 7/8/10): no `dependencies` edge,\n21\t     in either direction, between a license-validation and a repo-onboarding\n22\t     epic (Rule 7), a license-validation and a konflux-onboarding epic\n23\t     (Rule 8), or a konflux-onboarding and a general implementation epic\n24\t     (Rule 10) — these pairs must run in parallel; any real coupling is an\n25\t     acceptance-criterion gate, never a DAG edge. Edges into a docs-authoring\n26\t     epic are exempt (Rule 11 requires them).\n27\t  6. Work-type-extracted enforcement deliverable: a general Implementation\n28\t     epic whose TITLE names an enforcement tool (lint rule, CI check,\n29\t     static-analysis check, validation harness, enforcement) that shares its\n30\t     `component` with at least one other non-docs Implementation epic is a\n31\t     work-type extraction — the deliverable must be divided per surface into\n32\t     the consuming epics' Scope/ACs, not carved into a standalone epic.\n33\t     Exempt when the tool is the component's only implementation work.\n34\t\n35\tExit 0 with \"OK\" when clean; exit 1 with one line per violation otherwise.\n36\t\n37\tUsage:\n38\t    python3 skills/epic-decompose/scripts/validate_decomposition.py <STRAT_ID> \\\n39\t        [--artifacts-dir artifacts] [--components .context/rhai-components.txt]\n40\t    python3 skills/epic-decompose/scripts/validate_decomposition.py --self-check\n41\t\"\"\"\n42\t\n43\timport argparse\n44\timport os\n45\timport re\n46\timport sys\n47\t\n48\timport yaml\n49\t\n50\tSECTIONS = [(\"Description\", (\"description\",)),\n51\t            (\"Scope\", (\"scope\",)),\n52\t            (\"Acceptance Criteria\", (\"acceptance criteria\",)),\n53\t            (\"HLR Traceability\", (\"hlr traceability\", \"traceability\"))]\n54\t\n55\tPRIORITY_ORDER = {\"P0\": 0, \"P1\": 1, \"P2\": 2}\n56\t\n57\tIT_ENUM = (\"docs-authoring\", \"konflux-onboarding\", \"license-validation\",\n58\t           \"repo-onboarding\")\n59\t\n60\t# Pairs of implementation kinds that must run in parallel (no DAG edge either\n61\t# way) — parity with the implementation_type_rules judge.\n62\tPARALLEL_PAIRS = {\n63\t    frozenset((\"license-validation\", \"repo-onboarding\")): \"Rule 7\",\n64\t    frozenset((\"license-validation\", \"konflux-onboarding\")): \"Rule 8\",\n65\t    frozenset((\"konflux-onboarding\", \"general\")): \"Rule 10\",\n66\t}\n67\t\n68\tFRONTMATTER_RE = re.compile(r'^---\\s*\\n(.*?\\n)---\\s*\\n', re.DOTALL)\n69\t\n70\t# A general Implementation epic whose title matches this AND shares its\n71\t# component with another non-docs Implementation epic is a work-type\n72\t# extraction of a shared-surface enforcement deliverable (check 6).\n73\tENFORCEMENT_TITLE_RE = re.compile(\n74\t    r'\\b(lint|ci check|ci gate|static[- ]analysis|validation harness'\n75\t    r'|enforcement)\\b', re.I)\n76\t\n77\t\n78\tdef read_frontmatter(path):\n79\t    \"\"\"Return (frontmatter dict, body string) for a markdown file.\"\"\"\n80\t    with open(path, encoding=\"utf-8\") as f:\n81\t        content = f.read()\n82\t    m = FRONTMATTER_RE.match(content)\n83\t    if not m:\n84\t        return {}, content\n85\t    try:\n86\t        data = yaml.safe_load(m.group(1))\n87\t    except yaml.YAMLError:\n88\t        return {}, content\n89\t    if not isinstance(data, dict):\n90\t        return {}, content\n91\t    return data, content[m.end():]\n92\t\n93\t\n94\tdef body_headings(body):\n95\t    heads = []\n96\t    for hm in re.finditer(r'^#{1,6}\\s+(.+?)\\s*$', body, re.M):\n97\t        heads.append(re.sub(r'[^a-z ]', '', hm.group(1).lower()).strip())\n98\t    return heads\n99\t\n100\t\n101\tdef load_epics(artifacts_dir, strat_id):\n102\t    \"\"\"Return {epic_key: (path, frontmatter, body)} for one strategy's epics.\n103\t\n104\t    epic_key is the filename stem; branch files carry their BRANCH- prefix.\n105\t    \"\"\"\n106\t    task_dir = os.path.join(artifacts_dir, \"epic-tasks\")\n107\t    if not os.path.isdir(task_dir):\n108\t        return {}\n109\t    pat = re.compile(re.escape(strat_id) + r\"-(BRANCH-[A-Z]-)?(E\\d{3})\\.md$\")\n110\t    epics = {}\n111\t    for name in sorted(os.listdir(task_dir)):\n112\t        m = pat.match(name)\n113\t        if not m:\n114\t            continue\n115\t        path = os.path.join(task_dir, name)\n116\t        fm, body = read_frontmatter(path)\n117\t        epics[name[:-3]] = (path, fm, body)\n118\t    return epics\n119\t\n120\t\n121\tdef dependency_closure(start_key, deps):\n122\t    \"\"\"All epics reachable from start_key by following dependencies.\"\"\"\n123\t    seen, stack = set(), list(deps.get(start_key, []))\n124\t    while stack:\n125\t        n = stack.pop()\n126\t        if n in seen or n not in deps:\n127\t            continue\n128\t        seen.add(n)\n129\t        stack.extend(deps[n])\n130\t    return seen\n131\t\n132\t\n133\tdef check(strat_id, artifacts_dir, components_path):\n134\t    \"\"\"Run all checks; return a list of violation strings.\"\"\"\n135\t    probs = []\n136\t    epics = load_epics(artifacts_dir, strat_id)\n137\t    if not epics:\n138\t        return [\"no epic files found for %s under %s/epic-tasks/\"\n139\t                % (strat_id, artifacts_dir)]\n140\t\n141\t    valid_components = set()\n142\t    if os.path.isfile(components_path):\n143\t        with open(components_path, encoding=\"utf-8\") as f:\n144\t            valid_components = {ln.strip() for ln in f if ln.strip()}\n145\t    if not valid_components:\n146\t        probs.append(\"cannot read canonical component list %s — verify the \"\n147\t                     \"path before trusting component names\" % components_path)\n148\t\n149\t    deps, is_branch, is_docs, is_impl, itype, prio = {}, {}, {}, {}, {}, {}\n150\t    comps, titles = {}, {}\n151\t    for key, (path, fm, body) in epics.items():\n152\t        name = key + \".md\"\n153\t        # 1. body sections (contract parity with the artifact judge)\n154\t        heads = body_headings(body)\n155\t        for want, aliases in SECTIONS:\n156\t            if not any(a in h for h in heads for a in aliases):\n157\t                probs.append(\"%s: body missing '%s' section (required \"\n158\t                             \"sections: Description, Scope, Acceptance \"\n159\t                             \"Criteria, HLR Traceability)\" % (name, want))\n160\t        # 2. component vocabulary\n161\t        comp = fm.get(\"component\")\n162\t        if valid_components and isinstance(comp, str) and comp.strip() \\\n163\t                and comp.strip() not in valid_components:\n164\t            probs.append(\"%s: component '%s' is not in %s — pick the closest \"\n165\t                         \"canonical name (submit.py strips unknown names)\"\n166\t                         % (name, comp.strip(), components_path))\n167\t        # collect graph facts\n168\t        dl = fm.get(\"dependencies\")\n169\t        deps[key] = [x for x in dl if isinstance(x, str)] \\\n170\t            if isinstance(dl, list) else []\n171\t        is_branch[key] = \"BRANCH-\" in key\n172\t        is_docs[key] = fm.get(\"implementation_type\") == \"docs-authoring\"\n173\t        is_impl[key] = fm.get(\"type\") == \"Implementation\"\n174\t        comps[key] = comp.strip() if isinstance(comp, str) else \"\"\n175\t        it = fm.get(\"implementation_type\")\n176\t        itype[key] = it if it in IT_ENUM else None\n177\t        prio[key] = fm.get(\"priority\")\n178\t        titles[key] = fm.get(\"title\") if isinstance(fm.get(\"title\"), str) else \"\"\n179\t\n180\t    def kind(key):\n181\t        \"\"\"Implementation kind of an epic — parity with the judge: an epic\n182\t        that is not type Implementation is never a parallel-rule party; an\n183\t        Implementation epic's kind is its implementation_type when that is a\n184\t        known label, else 'general'.\"\"\"\n185\t        if not is_impl[key]:\n186\t            return \"non-implementation\"\n187\t        return itype[key] or \"general\"\n188\t\n189\t    # 3. Rule 11 — docs-authoring blocked by every main-plan Implementation\n190\t    universe = [k for k in epics\n191\t                if is_impl[k] and not is_docs[k] and not is_branch[k]]\n192\t    for k in sorted(epics):\n193\t        if not is_docs[k]:\n194\t            continue\n195\t        cl = dependency_closure(k, deps)\n196\t        missing = sorted(e for e in universe if e != k and e not in cl)\n197\t        if missing:\n198\t            probs.append(\"Rule 11: docs-authoring %s is not blocked by every \"\n199\t                         \"Implementation epic — add %s to its dependency chain\"\n200\t                         % (k, \", \".join(missing)))\n201\t\n202\t    # 4. Priority inheritance — enablers of P0 work must be P0\n203\t    for k in sorted(epics):\n204\t        if is_branch[k] or is_docs[k]:\n205\t            continue\n206\t        if prio.get(k) != \"P0\":\n207\t            continue\n208\t        # every main-plan, non-docs epic in k's closure enables P0 work\n209\t        cl = dependency_closure(k, deps)\n210\t        for t in sorted(cl):\n211\t            if is_branch[t] or is_docs[t]:\n212\t                continue\n213\t            if PRIORITY_ORDER.get(prio.get(t), 9) > 0:\n214\t                probs.append(\"priority inheritance: %s (%s) blocks P0 epic %s \"\n215\t                             \"but is %s — raise it to P0 or restructure\"\n216\t                             % (t, prio.get(t), k, prio.get(t)))\n217\t\n218\t    # 5. Rules 7/8/10 — implementation-type parallelism: the mandated-parallel\n219\t    #    pairs carry no dependencies edge in either direction (direct edges\n220\t    #    only; edges into a docs-authoring epic are exempt — Rule 11 requires\n221\t    #    them; dependencies naming epics with no file cannot be judged).\n222\t    for k in sorted(epics):\n223\t        if kind(k) == \"docs-authoring\":\n224\t            continue\n225\t        for t in deps[k]:\n226\t            if t not in epics:\n227\t                continue\n228\t            pair = frozenset((kind(t), kind(k)))\n229\t            rule = PARALLEL_PAIRS.get(pair)\n230\t            if rule:\n231\t                probs.append(\"%s: %s (%s) blocks %s (%s) — these must run in \"\n232\t                             \"parallel; remove the dependencies edge and \"\n233\t                             \"express any coupling as an AC gate on the \"\n234\t                             \"dependent epic\"\n235\t                             % (rule, t, kind(t), k, kind(k)))\n236\t\n237\t    # 6. Work-type-extracted enforcement deliverable — a general\n238\t    #    Implementation epic titled as an enforcement tool (lint rule, CI\n239\t    #    check, static analysis, validation harness) that shares its\n240\t    #    component with another non-docs Implementation epic is a work-type\n241\t    #    extraction of a shared-surface deliverable. Exempt when the tool is\n242\t    #    the component's only implementation work (no such sibling).\n243\t    for k in sorted(epics):\n244\t        if is_branch[k] or not is_impl[k] or is_docs[k] or kind(k) != \"general\":\n245\t            continue\n246\t        if not ENFORCEMENT_TITLE_RE.search(titles.get(k, \"\")):\n247\t            continue\n248\t        siblings = [t for t in epics\n249\t                    if t != k and not is_branch[t] and is_impl[t]\n250\t                    and not is_docs[t] and comps.get(t) == comps.get(k)\n251\t                    and comps.get(k)]\n252\t        if siblings:\n253\t            probs.append(\"%s: standalone enforcement deliverable (work-type \"\n254\t                         \"extraction) — the enforcement tool shares component \"\n255\t                         \"'%s' with %s. FIX: fold the enforcement work back \"\n256\t                         \"into every epic whose surface it covers — add the \"\n257\t                         \"part covering each epic's surface to that epic's \"\n258\t                         \"Scope plus a verification AC, delete this epic, and \"\n259\t                         \"update the decomposition summary. Do NOT keep a \"\n260\t                         \"standalone work-type epic.\"\n261\t                         % (k + \".md\", comps.get(k),\n262\t                            \", \".join(sorted(t + \".md\" for t in siblings))))\n263\t    return probs\n264\t\n265\t\n266\t# ─── self-check ───────────────────────────────────────────────────────────────\n267\t\n268\tdef _self_check():\n269\t    \"\"\"Verify each check fires on a minimal bad fixture and passes a good one.\"\"\"\n270\t    import shutil\n271\t    import tempfile\n272\t\n273\t    tmp = tempfile.mkdtemp(prefix=\"validate-decomp-selfcheck-\")\n274\t    try:\n275\t        art = os.path.join(tmp, \"artifacts\", \"epic-tasks\")\n276\t        os.makedirs(art)\n277\t        comp = os.path.join(tmp, \"components.txt\")\n278\t        with open(comp, \"w\") as f:\n279\t            f.write(\"Dashboard\\nServing Runtimes\\n\")\n280\t\n281\t        def write(name, fm, body):\n282\t            with open(os.path.join(art, name), \"w\") as f:\n283\t                f.write(\"---\\n%s\\n---\\n%s\" % (fm, body))\n284\t\n285\t        good_body = (\"# T\\n## Description\\nd\\n## Scope\\ns\\n\"\n286\t                     \"## Acceptance Criteria\\na\\n## HLR Traceability\\nh\\n\")\n287\t        write(\"RHAISTRAT-9001-E001.md\",\n288\t              \"component: Dashboard\\ntype: Implementation\\npriority: P0\\n\"\n289\t              \"dependencies: []\\n\", good_body)\n290\t        write(\"RHAISTRAT-9001-E002.md\",\n291\t              \"component: Serving Runtimes\\ntype: Implementation\\n\"\n292\t              \"implementation_type: docs-authoring\\npriority: P2\\n\"\n293\t              \"dependencies: [RHAISTRAT-9001-E001, RHAISTRAT-9001-E003,\"\n294\t              \" RHAISTRAT-9001-E004]\\n\",\n295\t              good_body)\n296\t        # a konflux-onboarding epic parallel to the general epic (no edge\n297\t        # either way) is the Rule 10-compliant shape — must not be flagged\n298\t        write(\"RHAISTRAT-9001-E003.md\",\n299\t              \"component: Dashboard\\ntype: Implementation\\n\"\n300\t              \"implementation_type: konflux-onboarding\\npriority: P1\\n\"\n301\t              \"dependencies: []\\n\", good_body)\n302\t        # an enforcement-tool epic in a component with NO other non-docs\n303\t        # Implementation epic (the tool is the only implementation work) is\n304\t        # the check-6-exempt shape — must not be flagged\n305\t        write(\"RHAISTRAT-9001-E004.md\",\n306\t              \"component: Serving Runtimes\\ntype: Implementation\\n\"\n307\t              \"priority: P1\\ndependencies: []\\n\"\n308\t              \"title: Validation harness for model serving\\n\", good_body)\n309\t        assert check(\"RHAISTRAT-9001\", os.path.join(tmp, \"artifacts\"),\n310\t                     comp) == [], \"good fixture must pass cleanly\"\n311\t\n312\t        # bad fixture: missing Scope, bad component, Rule 11 gap, P0->P1 edge,\n313\t        # Rule 10 konflux-onboarding -> general edge\n314\t        write(\"RHAISTRAT-9002-E001.md\",\n315\t              \"component: Model Serving Stack\\ntype: Implementation\\n\"\n316\t              \"priority: P0\\ndependencies: [RHAISTRAT-9002-E002]\\n\",\n317\t              \"# T\\n## Description\\nd\\n## Acceptance Criteria\\na\\n\"\n318\t              \"## HLR Traceability\\nh\\n\")\n319\t        write(\"RHAISTRAT-9002-E002.md\",\n320\t              \"component: Dashboard\\ntype: Implementation\\npriority: P1\\n\"\n321\t              \"dependencies: []\\n\", good_body)\n322\t        write(\"RHAISTRAT-9002-E003.md\",\n323\t              \"component: Dashboard\\ntype: Implementation\\n\"\n324\t              \"implementation_type: docs-authoring\\npriority: P2\\n\"\n325\t              \"dependencies: [RHAISTRAT-9002-E001]\\n\", good_body)\n326\t        # E004 is a main-plan Implementation the docs epic never depends on\n327\t        write(\"RHAISTRAT-9002-E004.md\",\n328\t              \"component: Dashboard\\ntype: Implementation\\npriority: P1\\n\"\n329\t              \"dependencies: [RHAISTRAT-9002-E005]\\n\", good_body)\n330\t        write(\"RHAISTRAT-9002-E005.md\",\n331\t              \"component: Dashboard\\ntype: Implementation\\n\"\n332\t              \"implementation_type: konflux-onboarding\\npriority: P1\\n\"\n333\t              \"dependencies: []\\n\", good_body)\n334\t        # E006 is a work-type-extracted enforcement deliverable: general\n335\t        # Implementation, enforcement title, same component as E004\n336\t        write(\"RHAISTRAT-9002-E006.md\",\n337\t              \"component: Dashboard\\ntype: Implementation\\npriority: P1\\n\"\n338\t              \"dependencies: []\\n\"\n339\t              \"title: CI lint rule enforcing structured log fields\\n\",\n340\t              good_body)\n341\t        probs = check(\"RHAISTRAT-9002\", os.path.join(tmp, \"artifacts\"), comp)\n342\t        joined = \"\\n\".join(probs)\n343\t        assert \"missing 'Scope'\" in joined, probs\n344\t        assert \"Model Serving Stack\" in joined, probs\n345\t        assert \"Rule 11\" in joined and \"E004\" in joined, probs\n346\t        assert \"priority inheritance\" in joined and \"E002\" in joined, probs\n347\t        r10 = [p for p in probs if p.startswith(\"Rule 10:\")]\n348\t        assert len(r10) == 1 and \"E005\" in r10[0] and \"E004\" in r10[0], probs\n349\t        c6 = [p for p in probs if \"standalone enforcement deliverable\" in p]\n350\t        assert len(c6) == 1 and \"E006\" in c6[0] and \"E004\" in c6[0], probs\n351\t        print(\"self-check OK: 6 checks fire on bad fixture, clean on good\")\n352\t        return 0\n353\t    finally:\n354\t        shutil.rmtree(tmp, ignore_errors=True)\n355\t\n356\t\n357\tdef main(argv=None):\n358\t    ap = argparse.ArgumentParser(description=__doc__)\n359\t    ap.add_argument(\"strat_id\", nargs=\"?\", help=\"e.g. RHAISTRAT-9013\")\n360\t    ap.add_argument(\"--artifacts-dir\", default=\"artifacts\")\n361\t    ap.add_argument(\"--components\",\n362\t                    default=\".context/rhai-components.txt\")\n363\t    ap.add_argument(\"--self-check\", action=\"store_true\")\n364\t    args = ap.parse_args(argv)\n365\t\n366\t    if args.self_check:\n367\t        return _self_check()\n368\t    if not args.strat_id:\n369\t        ap.error(\"strat_id is required (unless --self-check)\")\n370\t\n371\t    probs = check(args.strat_id, args.artifacts_dir, args.components)\n372\t    if probs:\n373\t        for p in probs:\n374\t            print(\"VIOLATION: %s\" % p)\n375\t        print(\"%d violation(s) — fix these before marking the decomposition \"\n376\t              \"complete\" % len(probs))\n377\t        return 1\n378\t    print(\"OK: contract checks passed for %s\" % args.strat_id)\n379\t    return 0\n380\t\n381\t\n382\tif __name__ == \"__main__\":\n383\t    sys.exit(main())\n384\t"}]},"parent_tool_use_id":"chatcmpl-tool-9164f842ed079c3c","agent_id":"aa58d3ccd41d49591","session_id":"cfc5c49c-9bde-4a05-b3d1-1a240781a747","uuid":"0252f898-5211-40db-88e7-1263c978f47d","timestamp":"2026-10-26T22:25:48.877Z","tool_result_meta":[{"id":"chatcmpl-tool-bd9a8eab3a6db326","permission_decision":{"decision":"accept","source":"config","reason_type":"mode"}}],"subagent_type":"claude","task_description":"Decompose RHAISTRAT-9020 into epics"}
